hooks.command:
file=$(echo '$CLAUDE_TOOL_INPUT' | python3 -c "import sys,json; d=json.load(sys.stdin); print(d.get('file_path',''))" 2>/dev/null); if echo "$file" | grep -q 'src/backend/agent.py'; then python3 -c "
import ast, sys
try:
    tree = ast.parse(open('src/backend/agent.py').read())
except: sys.exit(0)
for node in ast.walk(tree):
    if isinstance(node, ast.Call):
        func = getattr(node.func, 'attr', '') or getattr(node.func, 'id', '')
        if func == 'b64decode':
            print(f'WARNING [pre-edit]: b64decode at line {node.lineno} — ensure it is wrapped in try/except')
" 2>/dev/null; fi
